package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Propuesta de un servicio a un domiciliario con temporizador (tabla OFERTA, RF-M6-03, RN-05).
 * <p>
 * EN: Proposal of a delivery to a courier with a timer (OFERTA table, RF-M6-03, RN-05).
 */
@Entity
@Table(name = "OFERTA")
public class Offer {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del servicio. EN: The delivery id. */
    @Column(name = "SERVICIO_ID", nullable = false) private Long deliveryId;
    /** El id del domiciliario. EN: The courier id. */
    @Column(name = "DOMICILIARIO_ID", nullable = false) private Long courierId;
    /** El modo en que se ofreció. EN: The mode it was offered in. */
    @Column(name = "MODO", nullable = false, length = 12) private AssignmentMode mode;
    /** El estado de la oferta. EN: The offer status. */
    @Column(name = "ESTADO", nullable = false, length = 12) private OfferStatus status = OfferStatus.PENDING;
    /** La hora de envío. EN: The sending time. */
    @Convert(converter = MinutesConverter.class) @Column(name = "ENVIADA", nullable = false) private Double sent;
    /** La hora límite para responder. EN: The deadline to answer. */
    @Convert(converter = MinutesConverter.class) @Column(name = "LIMITE", nullable = false) private Double deadline;
    /** La hora de respuesta o cierre. EN: The answer or closing time. */
    @Convert(converter = MinutesConverter.class) @Column(name = "RESPONDIDA") private Double answered;
    /** El costo calculado por el motor. EN: The cost computed by the engine. */
    @Column(name = "COSTO") private Double cost;
    /** El motivo del rechazo. EN: The rejection reason. */
    @Column(name = "MOTIVO_RECHAZO", length = 200) private String rejectionReason;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected Offer() {}

    /**
     * Crea una oferta pendiente.
     * <p>
     * EN: Creates a pending offer.
     *
     * @param deliveryId id del servicio / delivery id
     * @param courierId id del domiciliario / courier id
     * @param mode modo en que se ofreció / mode it was offered in
     * @param sent hora de envío / sending time
     * @param deadline hora límite para responder / deadline to answer
     * @param cost costo calculado por el motor / cost computed by the engine
     */
    public Offer(long deliveryId, long courierId, AssignmentMode mode, double sent, double deadline, double cost) {
        this.deliveryId = deliveryId; this.courierId = courierId; this.mode = mode;
        this.sent = sent; this.deadline = deadline; this.cost = cost;
    }

    /**
     * Cierra la oferta con su resultado.
     * <p>
     * EN: Closes the offer with its result.
     *
     * @param result aceptada, rechazada, vencida o anulada / accepted, rejected, expired or voided
     * @param time hora de cierre / closing time
     * @param reason motivo del rechazo, puede ser null / rejection reason, may be null
     */
    public void close(OfferStatus result, double time, String reason) { status = result; answered = time; rejectionReason = reason; }

    /**
     * Indica si la oferta sigue esperando respuesta.
     * <p>
     * EN: Tells whether the offer is still waiting for an answer.
     *
     * @return true si está pendiente / true if it is pending
     */
    public boolean pending() { return status == OfferStatus.PENDING; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del servicio.
     * <p>
     * EN: Returns the delivery id.
     *
     * @return el id del servicio / the delivery id
     */
    public Long getDeliveryId() { return deliveryId; }

    /**
     * Devuelve el id del domiciliario.
     * <p>
     * EN: Returns the courier id.
     *
     * @return el id del domiciliario / the courier id
     */
    public Long getCourierId() { return courierId; }

    /**
     * Devuelve el modo en que se ofreció.
     * <p>
     * EN: Returns the mode it was offered in.
     *
     * @return el modo en que se ofreció / the mode it was offered in
     */
    public AssignmentMode getMode() { return mode; }

    /**
     * Devuelve el estado de la oferta.
     * <p>
     * EN: Returns the offer status.
     *
     * @return el estado de la oferta / the offer status
     */
    public OfferStatus getStatus() { return status; }

    /**
     * Devuelve la hora de envío.
     * <p>
     * EN: Returns the sending time.
     *
     * @return la hora de envío / the sending time
     */
    public Double getSent() { return sent; }

    /**
     * Devuelve la hora límite para responder.
     * <p>
     * EN: Returns the deadline to answer.
     *
     * @return la hora límite para responder / the deadline to answer
     */
    public Double getDeadline() { return deadline; }

    /**
     * Devuelve la hora en que se respondió o se cerró.
     * <p>
     * EN: Returns the time it was answered or closed.
     *
     * @return la hora o null / the time or null
     */
    public Double getAnsweredAt() { return answered; }

    /**
     * Devuelve el costo calculado por el motor.
     * <p>
     * EN: Returns the cost computed by the engine.
     *
     * @return el costo calculado por el motor / the cost computed by the engine
     */
    public Double getCost() { return cost; }

    /**
     * Devuelve el motivo del rechazo.
     * <p>
     * EN: Returns the rejection reason.
     *
     * @return el motivo del rechazo / the rejection reason
     */
    public String getRejectionReason() { return rejectionReason; }
}
